    resources = cfn.get_resources("AWS::ApiGateway::RestApi")
    if isinstance(resources, dict):
        params_in_template: Set[str] = set(cfn.template.get("Parameters", {}).keys())
        used_from_includes: Set[str] = set()
        cache: Dict[str, Set[str]] = {}
        for _, res in resources.items():
            props = res.get("Properties", {})
            body = props.get("Body")
            if not isinstance(body, dict):
                continue
            transform = body.get("Fn::Transform")
            if not isinstance(transform, dict):
                continue
            name = transform.get("Name")
            if name != "AWS::Include":
                continue
            t_params = transform.get("Parameters", {})
            if not isinstance(t_params, dict):
                continue
            location = t_params.get("Location")
            if not isinstance(location, str):
                continue
